const listWorkspaceIngressLog = `-- name: ListWorkspaceIngressLog :many
SELECT l.id, l.source_id, l.remote_id, l.filename, l.asset_id, l.status, l.error, l.duplicate_of_asset_id, l.imported_at FROM ingress_log l
JOIN ingress_sources s ON s.id = l.source_id
WHERE s.workspace_id = ?1
  AND (?2 IS NULL OR l.status = ?2)
ORDER BY l.imported_at DESC
LIMIT ?4 OFFSET ?3
`

type ListWorkspaceIngressLogParams struct {
	WorkspaceID string      `json:"workspace_id"`
	Status      interface{} `json:"status"`
	Offset      int64       `json:"offset"`
	Limit       int64       `json:"limit"`
}

func (q *Queries) ListWorkspaceIngressLog(ctx context.Context, arg ListWorkspaceIngressLogParams) ([]IngressLog, error) {
	rows, err := q.db.QueryContext(ctx, listWorkspaceIngressLog,
		arg.WorkspaceID,
		arg.Status,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []IngressLog{}
	for rows.Next() {
		var i IngressLog
		if err := rows.Scan(
			&i.ID,
			&i.SourceID,
			&i.RemoteID,
			&i.Filename,
			&i.AssetID,
			&i.Status,
			&i.Error,
			&i.DuplicateOfAssetID,
			&i.ImportedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

